ALTER TABLE app_user_role DROP CONSTRAINT app_user_role_pkey;
ALTER TABLE app_user_role ADD COLUMN id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY;
CREATE UNIQUE INDEX uq_app_user_role_active_relation
  ON app_user_role (user_id, role) WHERE deleted = FALSE;

